text:
{
  "title_novice": "От продуктивности к пороговой проницаемости",
  "summary": [
    {"text": "Граничную проницаемость K*пр рассчитывают по формуле, а не берут готовой.", "claims": ["c3"]},
    {"text": "Формула связывает граничный удельный коэффициент продуктивности, вязкость флюида и геометрию скважины.", "claims": ["c3", "c5", "c4"]},
    {"text": "Расчёт ведут для пластовых условий; результат задаёт границу коллектор — неколлектор.", "claims": ["c2", "c1"]}
  ],
  "claims": [
    {"key": "c1", "text": "K*пр характеризует границу между коллектором и неколлектором.", "kind": "inference", "unit_id": "u-009-fd03f0", "page": 9, "quote": "характеризующую границу коллектор — неколлектор, по формуле", "numbers": [], "question": null},
    {"key": "c2", "text": "Критическую величину рассчитывают для пластовых условий.", "kind": "assumption", "unit_id": "u-009-fd03f0", "page": 9, "quote": "для пластовых условий рассчитывают критическую величину", "numbers": [], "question": null},
    {"key": "c3", "text": "K*пр рассчитывают по формуле через η*пр, вязкость, радиусы и множитель 2π.", "kind": "inference", "unit_id": "u-010-be524f", "page": 10, "quote": "$$\\mathrm{K}_{\\mathrm{np}}^{*} = \\mu \\eta_{\\mathrm{np}}^{*} \\ln(\\mathrm{R}_{\\mathrm{s}}/\\mathrm{r}_{\\mathrm{c}})/2\\pi$$", "numbers": ["2"], "question": null},
    {"key": "c4", "text": "Rк — радиус контура питания скважины, rс — радиус скважины.", "kind": "observation", "unit_id": "u-010-01c084", "page": 10, "quote": "где $\\mathrm{R}_{\\mathrm{s}}$ — радиус контура питания скважины; $\\mathrm{r}_{\\mathrm{c}}$ — радиус скважины.", "numbers": [], "question": null},
    {"key": "c5", "text": "Вязкость берут для нефти (μн) или для газа (μг).", "kind": "observation", "unit_id": "u-009-fd03f0", "page": 9, "quote": "и используя значения вязкости нефти", "numbers": [], "question": null},
    {"key": "c6", "text": "Вязкость входит в формулу множителем, поэтому порог меняется при смене флюида.", "kind": "inference", "unit_id": "u-010-be524f", "page": 10, "quote": "$$\\mathrm{K}_{\\mathrm{np}}^{*} = \\mu \\eta_{\\mathrm{np}}^{*} \\ln(\\mathrm{R}_{\\mathrm{s}}/\\mathrm{r}_{\\mathrm{c}})/2\\pi$$", "numbers": [], "question": null}
  ],
  "mechanism": [
    {"text": "Формула переводит граничный удельный коэффициент продуктивности в граничную проницаемость.", "claims": ["c3"], "hypothesis": false},
    {"text": "Вязкость стоит в формуле множителем. При большей вязкости граничная проницаемость больше.", "claims": ["c6"], "hypothesis": false},
    {"text": "Геометрия скважины входит через ln(Rк/rс) и делитель 2π.", "claims": ["c3", "c4"], "hypothesis": false},
    {"text": "Формула — частный случай закона Дарси для установившегося радиального течения к скважине.", "claims": [], "hypothesis": true},
    {"text": "Логарифм отношения радиусов растёт медленно. Поэтому радиусы влияют на порог слабее, чем вязкость.", "claims": [], "hypothesis": true}
  ],
  "practice": [
    {"text": "Специалист берёт η*пр, найденный в предыдущем расчёте.", "claims": ["c3"], "hypothesis": false},
    {"text": "Он выбирает вязкость: μн для нефти или μг для газа, в пластовых условиях.", "claims": ["c5", "c2"], "hypothesis": false},
    {"text": "Он подставляет радиусы Rк и rс и вычисляет K*пр по формуле 1.2.", "claims": ["c4", "c3"], "hypothesis": false},
    {"text": "Итог — граница коллектор — неколлектор для данного флюида.", "claims": ["c1"], "hypothesis": false}
  ],
  "nuances": [
    {"text": "В формуле стоит общее μ, а в тексте — μн или μг. Нужный флюид выбирают отдельно.", "claims": ["c5", "c3"], "hypothesis": false},
    {"text": "Вязкость берут для пластовых условий, а не для условий на поверхности.", "claims": ["c2"], "hypothesis": true},
    {"text": "Значения Rк и rс в этих единицах не даны. Их задают по геометрии конкретной скважины.", "claims": [], "hypothesis": true}
  ],
  "deeper": [
    {"title": "Откуда берётся формула", "text": "Установившийся радиальный поток к скважине описывается законом Дарси. Формула 1.2 получается из него заменой дебита на η*пр.", "claims": [], "hypothesis": true},
    {"title": "Почему логарифм", "text": "Радиальный поток сходится к скважине. Логарифм отношения Rк/rс описывает этот сход.", "claims": [], "hypothesis": true}
  ],
  "procedure": [
    {"text": "Берут граничный удельный коэффициент продуктивности η*пр.", "claims": ["c3"]},
    {"text": "Берут вязкость нефти μн или газа μг для пластовых условий.", "claims": ["c5", "c2"]},
    {"text": "Подставляют значения в формулу 1.2 вместе с радиусами Rк и rс.", "claims": ["c3", "c4"]},
    {"text": "Получают критическую проницаемость K*пр — границу коллектор — неколлектор.", "claims": ["c1"]}
  ],
  "numbers_conditions": [
    {"text": "Вязкость берётся для пластовых условий.", "claims": ["c2"]},
    {"text": "Для нефти берут μн, для газа — μг.", "claims": ["c5"]},
    {"text": "В формуле 1.2 стоит делитель 2π.", "claims": ["c3"]}
  ],
  "terms_defined": [
    {"term": "граничная проницаемость Kпр*", "term_en": "critical permeability (cutoff)", "abbr": "K*пр", "definition": "Критическое значение проницаемости, отделяющее коллектор от неколлектора. Вычисляется по формуле 1.2, а не измеряется.", "claims": ["c1", "c3"]},
    {"term": "вязкость флюида", "term_en": "fluid viscosity", "abbr": "μ", "definition": "Свойство жидкости или газа сопротивляться течению. В формуле 1.2 берут вязкость нефти μн или газа μг.", "claims": ["c5"]},
    {"term": "радиус контура питания", "term_en": "drainage (supply) contour radius", "abbr": "Rк", "definition": "Радиус границы пласта, откуда флюид поступает к скважине. В главе назван только по имени; физический смысл здесь — гипотеза.", "claims": ["c4"]},
    {"term": "радиус скважины", "term_en": "wellbore radius", "abbr": "rс", "definition": "Радиус ствола скважины. Вместе с Rк задаёт геометрию в формуле 1.2.", "claims": ["c4"]},
    {"term": "пластовые условия", "term_en": "reservoir conditions", "abbr": "", "definition": "Давление и температура в самом пласте, а не на поверхности.", "claims": ["c2"]},
    {"term": "натуральный логарифм", "term_en": "natural logarithm", "abbr": "ln", "definition": "Логарифм по основанию e. В формуле 1.2 это ln(Rк/rс).", "claims": []},
    {"term": "флюид", "term_en": "fluid", "abbr": "", "definition": "Жидкость или газ в порах пласта: нефть, газ или вода.", "claims": []}
  ],
  "terms_used": [
    "граничное (критическое) значение",
    "критерий коллектора",
    "коллектор",
    "неколлектор",
    "удельный коэффициент продуктивности η*пр",
    "рентабельный дебит",
    "депрессия",
    "эффективная мощность",
    "коэффициент проницаемости (kпр)",
    "нефть",
    "газ"
  ],
  "formulas": [
    {
      "unit_id": "u-010-be524f",
      "label": "(1.2)",
      "latex": "\\mathrm{K}_{\\mathrm{пр}}^{*} = \\mu\\,\\eta_{\\mathrm{пр}}^{*}\\,\\ln(\\mathrm{R}_{\\mathrm{к}}/\\mathrm{r}_{\\mathrm{с}})/2\\pi",
      "meaning": "Граничная проницаемость равна вязкости, умноженной на граничный удельный коэффициент продуктивности и на ln(Rк/rс), делённым на 2π.",
      "variables": [
        {"symbol": "K*пр", "meaning": "граничная (критическая) проницаемость — порог коллектор / неколлектор", "unit": "не указана в тексте"},
        {"symbol": "μ", "meaning": "вязкость нефти μн или газа μг в пластовых условиях", "unit": "не указана в тексте"},
        {"symbol": "η*пр", "meaning": "граничный удельный коэффициент продуктивности (из предыдущего расчёта)", "unit": "не указана в тексте"},
        {"symbol": "Rк", "meaning": "радиус контура питания скважины", "unit": "не указана в тексте"},
        {"symbol": "rс", "meaning": "радиус скважины", "unit": "не указана в тексте"},
        {"symbol": "ln", "meaning": "натуральный логарифм", "unit": "безразмерна"},
        {"symbol": "2π", "meaning": "числовой множитель в знаменателе", "unit": "безразмерна"}
      ]
    }
  ],
