  "misconception": {
    "pack_id": null,
    "wrong": "Граничная проницаемость — готовое свойство породы, её берут с прибора, и вязкость флюида на неё не влияет.",
    "right": "K*пр рассчитывают по формуле через граничный удельный коэффициент продуктивности, вязкость флюида и геометрию скважины.",
    "claims": ["c3", "c5", "c6"]
  },
  "data_meaning": {
    "inputs": [
      {"text": "Граничный удельный коэффициент продуктивности η*пр из предыдущего расчёта.", "claims": ["c3"], "hypothesis": false},
      {"text": "Вязкость нефти μн или газа μг в пластовых условиях.", "claims": ["c5", "c2"], "hypothesis": false},
      {"text": "Радиусы: контура питания Rк и скважины rс.", "claims": ["c4"], "hypothesis": false}
    ],
    "outputs": [
      {"text": "Граничная проницаемость K*пр как порог коллектор / неколлектор.", "claims": ["c1", "c3"], "hypothesis": false}
    ],
    "breaks": [
      {"text": "Для нефти и газа порог считают с разной вязкостью, поэтому значения разные.", "claims": ["c5", "c6"], "hypothesis": false},
      {"text": "Если вязкость взята не для пластовых условий, порог будет смещён.", "claims": ["c2"], "hypothesis": true}
    ]
  },
  "it_analogy": {
    "pack_id": "IT03",
    "analogy": "Как порог классификатора, K*пр задаётся заранее из целевого показателя и формулы, а не подбирается по выборке. Здесь целевой показатель — граничный дебит, переведённый в η*пр.",
    "breaks_where": "Порог классификатора подбирают по данным. Здесь он вычисляется по физической формуле с вязкостью и геометрией скважины; выборки в этом узле нет."
  },
  "now_nuance": null,
  "threshold": {
    "is_threshold": true,
    "why": "Граничная проницаемость — расчётная величина, зависящая от экономики (η*пр), флюида (вязкость) и геометрии скважины. Без этого понимания не видно, почему порог разный для нефти и газа."
  },
  "inefficiency": {
