      "граничный удельный коэффициент продуктивности η*пр из предыдущего расчёта",
      "вязкость нефти μн или газа μг в пластовых условиях",
      "радиусы контура питания Rк и скважины rс"
    ],
    "manual_steps": [
      "выбрать вязкость: нефть или газ",
      "подставить значения в формулу 1.2 и вычислить K*пр",
      "(гипотеза) привести все величины к одной системе единиц"
    ],
    "judgment_points": [
      "какой флюид — нефть или газ — определяет выбор вязкости",
      "какие пластовые условия принять для вязкости",
      "(гипотеза) какой радиус контура принять для скважины"
    ],
    "time": [
      "(гипотеза) основное время уходит на сбор η*пр, вязкости и радиусов, а не на сам расчёт по формуле"
    ],
    "typical_errors": [
      "взять вязкость на поверхности вместо пластовой",
      "перепутать μн и μг",
      "принять граничное значение за измеренную проницаемость"
    ]
  },
