  "state_model": "Граничная проницаемость K*пр вычисляется из граничного η*пр, вязкости флюида μ и геометрии скважины (Rк, rс) по формуле 1.2.",
  "links": [
    {"target": "n02", "type": "prerequisite", "note": "η*пр и граничный дебит нужны для расчёта"},
    {"target": "n01", "type": "prerequisite", "note": "понятие граничного значения и критерия коллектора"},
    {"target": "n04", "type": "to_data", "note": "K*пр условен и зависит от принятого дебита"},
    {"target": "n05", "type": "to_data", "note": "K*пр переносят на пористость через корреляцию"}
  ],
  "typos": [
    {"unit_id": "u-010-be524f", "original": "\\mathrm{np}", "corrected": "\\mathrm{пр}", "note": "Подстрочный индекс «пр» распознан латиницей np. По смыслу это кириллица, как в тексте книги.", "confidence": "medium", "needs_scan_check": true},
    {"unit_id": "u-010-01c084", "original": "R_{s}", "corrected": "R_{к}", "note": "Индекс «к» (контур) распознан как латинская s. По смыслу — «контур питания».", "confidence": "medium", "needs_scan_check": true},
    {"unit_id": "u-010-01c084", "original": "r_{c}", "corrected": "r_{с}", "note": "Индекс «с» (скважина) распознан как латинская c. По смыслу — «радиус скважины».", "confidence": "medium", "needs_scan_check": true},
    {"unit_id": "u-009-fd03f0", "original": "k_{np}^{*}", "corrected": "K_{пр}^{*}", "note": "В тексте строчная k, в формуле (1.2) заглавная K. Подстрочный индекс — кириллица.", "confidence": "medium", "needs_scan_check": false},
    {"unit_id": "u-009-fd03f0", "original": "\\mu_{n}", "corrected": "\\mu_{н}", "note": "Индекс «н» (нефть) распознан как латинская n.", "confidence": "medium", "needs_scan_check": true},
    {"unit_id": "u-009-fd03f0", "original": "\\mu_{r}", "corrected": "\\mu_{г}", "note": "Индекс «г» (газ) распознан как латинская r.", "confidence": "medium", "needs_scan_check": true}
  ],
